using Microsoft.EntityFrameworkCore;

// Cosmos DB project context showing EF Core 9 breaking changes and fixes.
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change: The Cosmos provider now uses
            // "$type" instead of "Discriminator" for the discriminator property.
            // To keep compatibility with existing documents that use "Discriminator":
            entity.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

// EF Core 9 breaking change: Synchronous I/O on Cosmos DB is no longer supported.
// All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.).
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 - worked but is now broken in EF Core 9):
    // public List<Product> GetProducts() => _db.Products.ToList();

    // AFTER (EF Core 9 - must use async):
    public async Task<List<Product>> GetProductsAsync()
    {
        return await _db.Products.ToListAsync();
    }

    // BEFORE:
    // public Product? Find(string id) => _db.Products.FirstOrDefault(p => p.Id == id);

    // AFTER:
    public async Task<Product?> FindAsync(string id)
    {
        return await _db.Products.FirstOrDefaultAsync(p => p.Id == id);
    }
}

